let clientSection='summary',clientChoice=null;
function readPreference(){try{return JSON.parse(localStorage.getItem('clarity-preference')||'null')}catch{return null}}
function currentPreference(){let p=readPreference();return p&&p.inputs.client===state.client?p:null}
function preferenceFresh(p){return p&&JSON.stringify(p.inputs)===JSON.stringify(state)}
function clientReviewHTML(){let p=currentPreference();return p?`<section class="panel preference-panel"><div class="panel-head"><h2>Client’s preference</h2><span class="tag ${preferenceFresh(p)?'':'warn'}">${preferenceFresh(p)?'Awaiting RM review':'Plan changed · reconfirm'}</span></div><strong>${esc(p.label)}</strong><p class="sub">${esc(p.note||'No additional note.')}</p><p class="small">${new Date(p.date).toLocaleString('en-IN')} · ${names[p.product]} · Saved on this device. Not an investment instruction.</p></section>`:''}
function clientDashboard(){const up=E.payoff(state,state.up),down=E.payoff(state,state.down),flat=E.payoff(state,state.flat),fits=E.checks(state).every(c=>c.ok);return title('YOUR MONEY, MADE CLEAR',`Hello, ${esc(state.client.split(' ')[0])}.`,'Let’s see how your money could support '+esc(state.goal.toLowerCase())+'.',`<div class="actions" style="margin-top:0"><button class="btn" data-go="scenarios">Explore calculations ↗</button><button class="btn" data-summary-download>Download summary ↓</button></div>`)+`<div class="client-tabs" role="tablist" aria-label="Client dashboard">${[['summary','My goal'],['options','My options'],['decision','My decision'],['documents','My reports']].map(([id,label])=>`<button role="tab" aria-selected="${clientSection===id}" data-client-section="${id}" class="${clientSection===id?'active':''}">${label}</button>`).join('')}</div>`+({summary:()=>`<section class="client-hero"><div><div class="eyebrow">THE GOAL THAT MATTERS</div><h2>${esc(state.goal)}</h2><p class="sub">You have ${state.years} years to turn ${money(state.amount)} into ${money(state.target)}.</p><div class="hero-stats"><div><span>Starting with</span><strong>${money(state.amount)}</strong></div><div class="goal-arrow">⟶</div><div><span>Working towards</span><strong>${money(state.target)}</strong></div></div></div><div class="goal-emblem" aria-hidden="true">↗</div></section><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Your plan, at a glance</h2><p class="sub">${names[state.product]} · ${state.term}-year holding period</p></div>${badge(fits)}</div><div class="client-outcomes">${[['Market falls',state.down,down,'#bd9461'],['Market stays flat',state.flat,flat,'#99a985'],['Market rises',state.up,up,'#468566']].map(([label,r,v,c])=>`<div><span class="outcome-dot" style="background:${c}"></span><div class="small">${label} (${r>0?'+':''}${r}%)</div><strong>${money(v)}</strong><span class="small">at maturity</span></div>`).join('')}</div>${payoffChart()}<p class="small">The graph links total market change to your payout at maturity. These are possibilities, not forecasts.</p></section><section class="panel"><h2>Can this meet your goal?</h2><div class="client-gap"><span class="small">Gap in the upside example</span><strong>${money(Math.max(0,state.target-up))}</strong></div><p class="sub">${up<state.target?'Even the selected upside example leaves you short. Discuss the target, amount, or product with your manager.':'The upside example reaches your target. Other market outcomes may not.'}</p><div class="row between"><span>You can accept losing</span><strong>${money(state.amount*state.loss/100)}</strong></div><div class="row between"><span>Early access needed</span><strong>${state.liquidity==='yes'?'Yes':'No'}</strong></div><button class="btn primary" data-client-section="options" style="margin-top:20px">Review my options ↗</button></section></div><section class="panel"><div class="panel-head"><h2>Three things to know</h2><span class="tag">PLAIN & SIMPLE</span></div><div class="client-essentials"><div><span>01</span><h3>Your money may be tied up</h3><p class="small">${state.product==='equity'?'You can redeem at market value, which can be below your investment.':`This model assumes you hold for ${state.term} years. Early withdrawal is not included.`}</p></div><div><span>02</span><h3>${state.product==='protected'?'Growth has a limit':state.product==='deposit'?'Growth follows a fixed formula':'Your principal is at risk'}</h3><p class="small">${state.product==='protected'?`Your total return is capped at ${state.cap}% before fees. The maturity floor is ${state.floor}% of principal before fees, assuming the issuer pays.`:state.product==='deposit'?`${state.rate}% annually, compounded for ${state.term} years, assuming the issuer pays.`:'A full market loss could mean losing all your investment.'}</p></div><div><span>03</span><h3>Keep costs in the picture</h3><p class="small">${money(state.amount*state.fee/100)} is deducted once at maturity. Values exclude tax. A past result is not a promise.</p></div></div></section>`,options:()=>`<div class="section-label"><h2>Your choices, side by side</h2><p class="sub">${money(state.amount)} invested for ${state.term} years in every example.</p></div><div class="product-grid client-products">${Object.keys(names).map(p=>{let checks=E.checks(state,p),ok=checks.every(c=>c.ok);return `<section class="product ${p===state.product?'selected':''}"><div class="between"><span class="tag">${p===state.product?'Manager’s selection':'Alternative'}</span></div><h2 style="margin-top:24px">${names[p]}</h2><p>${p==='protected'?'A maturity floor, with limited upside.':p==='deposit'?'A fixed growth formula over time.':'Market growth and market losses.'}</p>${[['Falls',state.down],['Flat',state.flat],['Rises',state.up]].map(([l,r])=>`<div class="row between"><span>${l} (${r}%)</span><strong>${money(E.payoff(state,r,p))}</strong></div>`).join('')}<div style="margin:20px 0">${badge(ok)}</div><p>${checks.filter(c=>!c.ok).map(c=>esc(c.name)).join(' · ')||'Passes the model’s checks. The goal is not guaranteed.'}</p><button class="btn ${ok?'primary':''}" data-client-pick="${p}">${ok?'Choose to discuss':'Ask about this option'} ↗</button></section>`}).join('')}</div><section class="panel"><h2>What “fits” means here</h2><p class="sub">We check your timing, ability to bear loss, need for early access, and whether the target is possible under the rules. Passing these checks is a starting point for discussion.</p><p class="small" style="margin-top:14px">All options use the manager’s configured term and fee. A maturity floor does not cover issuer default. The market option can lose 100% of principal.</p></section>`,decision:()=>{let p=currentPreference(),choice=clientChoice||state.product,ok=E.checks(state,choice).every(c=>c.ok);return `<div class="grid"><form class="panel" id="client-decision-form"><div class="panel-head"><h2>What would you like to do?</h2><span class="tag">YOUR PREFERENCE</span></div><label class="field">Option to discuss<select name="choice" id="client-choice">${Object.keys(names).map(id=>`<option value="${id}" ${choice===id?'selected':''}>${names[id]}</option>`).join('')}</select></label><div class="${ok?'info':'notice'}" style="margin-top:20px">${ok?'This option passes the current model checks. Your manager still needs to review it with you.':'This option does not meet all your current requirements. You can ask for changes or pause the decision.'}</div><label class="field">My next step<select name="intent">${ok?'<option value="discuss">I prefer this option — discuss next steps</option>':''}<option value="revise">I want to revise the plan</option><option value="question">I have a question for my manager</option><option value="pause">I’m not ready to invest</option></select></label><label class="field" style="margin-top:22px">Anything you’d like your manager to know?<textarea name="note" rows="4" maxlength="2000" placeholder="Your question, concern, or reason…"></textarea></label><label class="check" style="margin-top:20px"><input type="checkbox" required>I understand that these are possible outcomes, and I have reviewed the risks and target gap.</label><div class="actions"><button class="btn primary">Save my preference ↗</button></div><p class="small" style="margin-top:15px">Saved for the manager’s review on this browser. This does not place an investment or send a message.</p></form><div><section class="panel"><h2>Your latest preference</h2>${p?`<div style="margin:20px 0"><span class="tag ${preferenceFresh(p)?'':'warn'}">${preferenceFresh(p)?'Saved for review':'Plan changed'}</span></div><h3>${esc(p.label)}</h3><p class="sub">${names[p.product]}</p><p class="small">${esc(p.note||'No additional note.')}</p><p class="small" style="margin-top:20px">${new Date(p.date).toLocaleString('en-IN')}</p>${!preferenceFresh(p)?'<div class="notice" style="margin-top:20px">Your plan has changed. Review it and save a new preference.</div>':''}`:'<p class="sub">Take your time. No preference saved yet.</p>'}</section><section class="panel"><h2>Before you decide</h2><div class="checks" style="margin-top:22px">${checksHTML(choice)}</div></section></div></div>`},documents:()=>{let docs=records.filter(r=>r.client===state.client);return `<section class="panel"><div class="panel-head"><div><h2>Your plan summary</h2><p class="sub">A plain-language copy of the current plan and your preference.</p></div><button class="btn primary" data-summary-download>Download ↓</button></div><div class="info">Keep a copy to discuss with your family or relationship manager.</div></section><section class="panel"><h2>Reviewed decisions</h2><p class="sub">Reports saved by your relationship manager for ${esc(state.client)}.</p>${docs.length?docs.map(r=>`<div class="row between"><div><h3>${esc(r.decisionLabel)}</h3><p class="small">${new Date(r.date).toLocaleDateString('en-IN')} · ${names[r.inputs.product]}</p></div><button class="btn" data-download="${records.indexOf(r)}">Download report ↓</button></div>`).join(''):'<div class="empty">Your manager’s report will appear here after review.</div>'}</section>`}}[clientSection])()}
function renderClient(){document.body.classList.add('client-mode');$('.avatar').textContent=state.client.trim().split(/\s+/).map(n=>n[0]).slice(0,2).join('').toUpperCase();$('.workspace').textContent='YOUR INVESTMENT SPACE';$('#nav').innerHTML=`<a href="#client-view" class="active" aria-current="page"><span class="nav-icon">◫</span>My dashboard</a><a href="#overview"><span class="nav-icon">⇄</span>Manager workspace</a>`;$('#breadcrumb').textContent='Client dashboard';$('#app').innerHTML=clientDashboard();bind();bindClient()}
function bindClient(){document.querySelectorAll('[data-client-section]').forEach(b=>b.onclick=()=>{clientSection=b.dataset.clientSection;render()});document.querySelectorAll('[data-client-pick]').forEach(b=>b.onclick=()=>{clientChoice=b.dataset.clientPick;clientSection='decision';render()});document.querySelectorAll('[data-summary-download]').forEach(b=>b.onclick=downloadClientSummary);$('#client-choice')?.addEventListener('change',e=>{clientChoice=e.target.value;render()});$('#client-decision-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),product=f.get('choice'),intent=f.get('intent');if(intent==='discuss'&&!E.checks(state,product).every(c=>c.ok)){toast('This option needs changes before proceeding.');return}const labels={discuss:'Discuss my preferred option',revise:'Revise my plan',question:'A question for my manager',pause:'Not ready to invest'};let p={date:new Date().toISOString(),product,intent,label:labels[intent],note:f.get('note').trim(),inputs:{...state},acknowledged:true};try{localStorage.setItem('clarity-preference',JSON.stringify(p));render();toast('Preference saved for manager review')}catch{toast('Unable to save on this device. Please try again.')}})}
function downloadClientSummary(){let p=currentPreference(),s=state;let text=`CLARITY — YOUR INVESTMENT SUMMARY\nPrepared: ${new Date().toLocaleString('en-IN')}\n\nHello ${s.client},\nYour goal: ${s.goal}\nStarting amount: ${money(s.amount)}\nTarget: ${money(s.target)} in ${s.years} years\nLoss you can accept: ${money(s.amount*s.loss/100)} (${s.loss}%)\nEarly access needed: ${s.liquidity}\n\nOPTION UNDER DISCUSSION\n${names[s.product]}\nHolding period: ${s.term} years\nFee: ${s.fee}% of initial principal, deducted once at maturity\n${s.product==='protected'?`Total return cap: ${s.cap}%; participation: ${s.participation}%; maturity principal floor: ${s.floor}% before fees.`:s.product==='deposit'?`Annual compounded rate: ${s.rate}%`:'Full market participation; the entire principal can be lost.'}\n\nPOSSIBLE OUTCOMES\n${[['Market falls',s.down],['Market stays flat',s.flat],['Market rises',s.up]].map(([l,r])=>`${l} (${r}%): ${money(E.payoff(s,r))}`).join('\n')}\nGap in upside example: ${money(Math.max(0,s.target-E.payoff(s,s.up)))}\n\nDOES IT FIT?\n${E.checks(s).map(c=>(c.ok?'PASS':'REVIEW')+' — '+c.name+': '+c.detail).join('\n')}\n\nALTERNATIVES: fall / flat / rise\n${Object.keys(names).map(id=>names[id]+': '+[s.down,s.flat,s.up].map(r=>money(E.payoff(s,r,id))).join(' / ')).join('\n')}\n\nYOUR PREFERENCE\n${p?`${p.label} — ${names[p.product]}\n${p.note}\n${preferenceFresh(p)?'Applies to current plan':'Plan changed; reconfirm this preference'}`:'No preference recorded.'}\n\nNEXT STEP\nDiscuss the risks, target gap and choice with your manager. No investment has been placed.\n\nAll products are illustrative. Values exclude tax. Fixed returns and floors assume the issuer pays; issuer default is not modelled. Early withdrawal is not modelled for the note or deposit. Market results and reaching a goal are not guaranteed. Preferences and reports are stored only in this browser.\n`;let url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='clarity-client-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
window.addEventListener('storage',e=>{if(['clarity-state','clarity-records','clarity-preference'].includes(e.key)){try{state={...E.defaults,...JSON.parse(localStorage.getItem('clarity-state')||'{}')};records=JSON.parse(localStorage.getItem('clarity-records')||'[]');render()}catch{}}});
